  for (int(j) = 0; (j) < (int)(1 << logw); ++(j)) {
    for (int(i) = 0; (i) < (int)(1 << logh); ++(i)) tmp[i] = A[i][j];
    fft(logh, tmp.data());
    for (int(i) = 0; (i) < (int)(1 << logh); ++(i)) A[i][j] = tmp[i];
  }
}
void FFT2Dinv(int logh, int H, int logw, int W, vector<vector<Ring>> &A) {
  vector<Ring> tmp(1 << logh);
