bitset<Maxn> R[Maxn], G[26][Maxn];
bitset<Maxn> calc(const bitset<Maxn>& b, int len, int l) {
  return (b >> l) | (b << (len - l));
}
void solve() {
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; i++) scanf("%s", P[i]);
  scanf("%d%d", &r, &c);
