    for (int j = 0; j < m + c; j++) P[i][j] = P[i % n][j % m];
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) R[i].set(j);
  for (int ch = 0; ch < 26; ch++)
    for (int i = 0; i < n + r; i++)
      for (int j = 0; j < m + c; j++)
        if (P[i][j] == ch + 'a') G[ch][i].set(j);
