void getConnectedComponent(int i) {
  index_[i] = INDEX;
  lowLink[i] = INDEX;
  INDEX++;
  stk.push(i);
  onStack[i] = true;
  for (int nxt : adj[i]) {
    if (index_[nxt] == -1) {
      getConnectedComponent(nxt);
      lowLink[i] = min(lowLink[i], lowLink[nxt]);
    } else if (onStack[nxt]) {
      lowLink[i] = min(lowLink[i], index_[nxt]);
    }
  }
  if (lowLink[i] == index_[i]) {
    vector<int> comp;
    int poped;
    do {
      poped = stk.top();
      stk.pop();
      onStack[poped] = false;
