		rep(j,m) cin>>ds[j];
		rep(j,m) cin>>fs[j];
		rep(j,m) g.AddEdge(i,ds[j],abs(cs[ds[j]]-cs[i]),fs[j]);
	}
	double res=MinCostFlow(g,s,t,f);
	if(res==-1)
		puts("impossible");
	else
		printf("%.10f\n",res);
}

int main()
{
	int tc; cin>>tc;
	rep(_,tc) solve();
}

