struct QuickFind{
  Int n;
  vector<Int> r,p;
  vector<vector<Int> > v;
  QuickFind(){}
  QuickFind(Int sz):n(sz),r(sz),p(sz),v(sz){
    for(Int i=0;i<n;i++){
      r[i]=1,p[i]=i;
      v[i].resize(1,i);
    }
  }
  bool same(Int x,Int y){
    return p[x]==p[y];
  }
  void unite(Int x,Int y){
    x=p[x];y=p[y];
    if(x==y) return;
    if(r[x]<r[y]) swap(x,y);
    r[x]+=r[y];
    for(Int i=0;i<(Int)v[y].size();i++){
      p[v[y][i]]=x;
      v[x].push_back(v[y][i]);
    }
    v[y].clear();
  }
  Int find(Int v){return p[v];};
};

struct SCC{
  Int n;
  vector<vector<Int> > G,rG,T,C;
  vector<Int> vs,used,belong;
  SCC(){}
  SCC(Int sz):n(sz),G(sz),rG(sz),used(sz),belong(sz){}

  void add_edge(Int from,Int to){
    G[from].push_back(to);
    rG[to].push_back(from);
  }

  void input(Int m,Int offset=0){
    Int a,b;
    for(Int i=0;i<m;i++){
      cin>>a>>b;
      add_edge(a+offset,b+offset);
    }
  }

  void dfs(Int v){
    used[v]=1;
    for(Int i=0;i<(Int)G[v].size();i++){
      if(!used[G[v][i]]) dfs(G[v][i]);
    }
    vs.push_back(v);
  }

  void rdfs(Int v,Int k){
    used[v]=1;
    belong[v]=k;
    C[k].push_back(v);
    for(Int i=0;i<(Int)rG[v].size();i++){
      if(!used[rG[v][i]]) rdfs(rG[v][i],k);
    }
  }

  Int build(){
    fill(used.begin(),used.end(),0);
    vs.clear();
    for(Int v=0;v<n;v++){
      if(!used[v]) dfs(v);
    }
    fill(used.begin(),used.end(),0);
    Int k=0;
    for(Int i=vs.size()-1;i>=0;i--){
      if(!used[vs[i]]){
	T.push_back(vector<Int>());
	C.push_back(vector<Int>());
	rdfs(vs[i],k++);
      }
    }
    for(Int i=0;i<n;i++)
      for(Int u:G[i])
	if(belong[i]!=belong[u])
	  T[belong[i]].push_back(belong[u]);
    for(Int i=0;i<k;i++){
      sort(T[i].begin(),T[i].end());
      T[i].erase(unique(T[i].begin(),T[i].end()),T[i].end());
    }
    return k;
  }
};

