    x[i]--;y[i]--;
    if(w[i]==2){
      if(uf.same(x[i],y[i])) inf();
      uf.unite(x[i],y[i]);
      G[x[i]].emplace_back(y[i]);
      G[y[i]].emplace_back(x[i]);
    }
  }

  vector<Int> v;
  for(Int i=0;i<n;i++)
    if(uf.find(i)==i) v.emplace_back(i);

  Int k=v.size();
