  for(Int i=0;i<k;i++)
    vs.emplace_back(v[scc.C[i][0]]);

  reverse(vs.begin(),vs.end());

  function<Int(int,Int)> dfs=[&](Int v,Int p)->Int{
    Int res=dp1[v];
    for(Int u:G[v]){
      if(u==p) continue;
      chmax(res,dfs(u,v)+1);
    }
    return dp2[v]=res;
  };

  function<void(Int,int,Int)> dfs2=[&](Int v,Int p,Int d)->void{
    using P = pair<Int, Int>;
    vector<P> ds;
    ds.emplace_back(d,p);
    ds.emplace_back(dp1[v],v);
    for(Int u:G[v]){
      if(u==p) continue;
      ds.emplace_back(dp2[u]+1,u);
    }
    sort(ds.rbegin(),ds.rend());
    for(Int u:G[v]){
      if(u==p) continue;
      dfs2(u,v,ds[u==ds[0].second].first+1);
    }
    chmax(dp2[v],d);
  };

  for(Int x:vs){
    for(Int v:uf.v[x])
      for(Int u:H[v])
	chmax(dp1[v],dp2[u]+1);
    //cout<<x<<endl;
    dfs(x,-1);
    dfs2(x,-1,0);
  }

  if(0) 
    for(Int i=0;i<n;i++)
      cout<<i<<":"<<dp1[i]<<" "<<dp2[i]<<endl;

  Int ans=0;
  for(Int x:dp2) chmax(ans,x);
  cout<<ans<<endl;
  return 0;
}

