    cin >> a >> b;
    --a, --b;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }
  dfs(0, -1);
  dfs2(0, 0);
  for(int i = 0; i < N; i++) {
    cout << ans[i] << endl;
  }
}

