  cplx x, y;
  for (int i = 1; i < n; i <<= 1) {
    cplx w1(cos(PI / i), sin(type * PI / i));
    for (int j = 0; j < n; j += i << 1) {
      cplx w(1, 0);
      for (int k = 0; k < i; k++) {
        x = a[j + k], y = w * a[j + k + i];
        a[j + k] = x + y, a[j + k + i] = x - y;
        w *= w1;
      }
    }
  }
  if (type == -1) {
    for (int i = 0; i < n; i++) a[i].a /= n, a[i].b /= n;
  }
}
