  while (k) {
    if (k & 1) ret = 1LL * ret * x % (119 * (1 << 23) + 1);
    x = 1LL * x * x % (119 * (1 << 23) + 1);
    k >>= 1;
  }
  return ret;
}
void NTT(int *a, int n, int type) {
