    ans++;
    nx = -1;
    ny = -1;
    if (v == 0) {
      for (int i = y - 1; i >= 0 && ny == -1;)
        if (p[x][i] >= 0)
          ny = i;
        else
          i -= t[m * x + i][0];
      if (ny == -1) break;
      for (int i = y; i >= ny;) {
        tmp = i;
        i -= t[m * x + i][0];
        t[m * x + tmp][0] = tmp - ny + 1;
      }
      y = ny;
    } else if (v == 1) {
      for (int i = y + 1; i < m && ny == -1;)
        if (p[x][i] >= 0)
          ny = i;
        else
          i += t[m * x + i][1];
      if (ny == -1) break;
      for (int i = y; i <= ny;) {
        tmp = i;
        i += t[m * x + i][1];
        t[m * x + tmp][1] = ny - tmp + 1;
      }
      y = ny;
    } else if (v == 2) {
      for (int i = x - 1; i >= 0 && nx == -1;)
        if (p[i][y] >= 0)
          nx = i;
        else
          i -= t[i * m + y][2];
      if (nx == -1) break;
      for (int i = x; i >= nx;) {
        tmp = i;
        i -= t[i * m + y][2];
        t[tmp * m + y][2] = tmp - nx + 1;
      }
      x = nx;
    } else if (v == 3) {
      for (int i = x + 1; i < n && nx == -1;)
        if (p[i][y] >= 0)
          nx = i;
        else
          i += t[i * m + y][3];
      if (nx == -1) break;
      for (int i = x; i <= nx;) {
        tmp = i;
        i += t[i * m + y][3];
        t[tmp * m + y][3] = nx - tmp + 1;
      }
      x = nx;
    } else
      break;
  }
  return ans;
}
