int ComputeDistance(int x1,int x2,int w){
  // ..x1....x2.. dist = min(x2-x1,(col-x2)+x1);
  // ..x2....x1.. dist = min(x1-x2,(col-x1)+x2);
  return x1 < x2 ? min(x2-x1,(w-x2)+x1) : min(x1-x2,(w-x1)+x2);
}

int ComputeCandidateNum(int x1,int x2,int w){
  if(x1 < x2){
    if(x2-x1 != (w-x2)+x1){
      return 1;
    }
    else{
      return 2;
    }
  }
  else{
    if(x1-x2 != (w-x1)+x2){
      return 1;
    }
    else{
      return 2;
    }
  }
}

