						swap(p1,p2);
					}

					polygon = ConvexCut(polygon,p1,p2);
				}
			}


			if(!FLG)continue;

			//重心.x < x+1
			if(fabs(num_A*(x+1)-vec_A.x) < EPS && fabs(num_B*(x+1)-vec_B.x) < EPS){

