    }
    ll res = inv_count();
    ll rem = res - K;
    vi hoge(n,1);
    segtree<int> sg(n);
    segtree_<int> bt(hoge);
    if(rem <= 0){
        rep(i,n){
            out(x[i]+1);
        }
        return 0;
    }
    // show(rem);
    vector<bool> used(n, false);
