                    out(x[j]+1);
                }
            }
            break;
        }else{
            int id = n-1;
            if(rem < n-i){
                id = bt.query_(rem);
            }
            // show(id);
            int num = sg.query(0,id+1);
            // show(num);
            used[num] = true;
            out(num+1);
            // show(g[num]);
            rem -= bt.query(0, g[num]);
            // show(rem);
            sg.update(g[num],INF);
            bt.update(g[num]);
        }
    }
    return 0;
}

