		//cout << "k " << k << endl;
		if(i > 60){
			if(k % 2)ans.PB(1);
			else ans.PB(0);
			k /= 2;
		}
		else {
			bool ok = false;
			ll a = (k / 2);
			ll b = (k / 2) + n / 2;
			//cout << "ab " << a << " " << b << endl;
			for(auto it = s[i-1].begin();it != s[i-1].end();it++){
				if(it -> FI <= a && a < it -> SE){
					if(k%2)ans.PB(1);
					else ans.PB(0);
					k = a;
					ok = true;
					break;
				}
				if(it -> FI <= b && b < it -> SE){
					if(k%2)ans.PB(0);
					else ans.PB(1);
					k = b;
					ok = true;
					break;
				}
			}
			if(!ok){
				cout << -1 << endl;
				return 0;
			}
		}
	}

	REP(i,q)cout << ans[i] << endl;


	return 0;
