  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout.tie(nullptr);
  cin >> n >> q;
  for (long long i = 1; i <= n; i++) {
    cin >> a[i];
  }
  buildSegmentTree(1, 1, n);
  while (q--) {
    long long tp, x, y;
    cin >> tp >> x >> y;
    if (tp == 1) {
      performMaxQuery(1, 1, n, 1, x, y);
    } else {
      cout << moveAndBuyMaxNumberQuery(1, 1, n, x, n, y) << '\n';
    }
  }
  return 0;
}

