  if (!cnt[pos]++) Insert(1, pos, v[pos - 1]);
}
void Del(int pos) {
  pos = lower_bound(v.begin(), v.end(), a[pos]) - v.begin() + 1;
  if (!--cnt[pos]) Remove(1, pos);
