void add_value(int x) {
  if (counters[x] == 0) {
    switch_on(x);
  }
  counters[x] += 1;
}
void delete_value(int x) {
  if (counters[x] == 1) {
    switch_off(x);
  }
  counters[x] -= 1;
}
