void solve() {
  int n;
  scanf("%d%d", &n, &MOD);
  for (int i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
  }
  h = compress_a(n, a, real_a);
  build_tree(1, 1, h);
  int q;
  scanf("%d", &q);
  for (int it = 0; it < q; it++) {
    int l, r;
    scanf("%d%d", &l, &r);
    queries[it].l = l;
    queries[it].r = r;
    queries[it].id = it;
  }
  sort(queries, queries + q, cmp_queries);
  int l = queries[0].l;
  int r = queries[0].r;
  for (int i = l; i <= r; i++) {
    add_value(a[i]);
  }
  answer[queries[0].id] = get_answer();
  for (int i = 1; i < q; i++) {
    while (r < queries[i].r) {
      r += 1;
      add_value(a[r]);
    }
    while (queries[i].l < l) {
      l -= 1;
      add_value(a[l]);
    }
    while (r > queries[i].r) {
      delete_value(a[r]);
      r -= 1;
    }
    while (queries[i].l > l) {
      delete_value(a[l]);
      l += 1;
    }
    answer[queries[i].id] = get_answer();
  }
  for (int i = 0; i < q; i++) {
    printf("%d\n", answer[i]);
  }
}
