ll sm[N];

ll ap = 0;
ll aq = 1;

ll gcd(ll a, ll b) {
    while (b) {
        ll q = a % b;
        a = b;
        b = q;
    }
    return a;
}

using lll = __int128_t;

void upd(ll p, ll q) {
    ll g = gcd(p, q);
    p /= g, q /= g;
    if (lll(ap) * q < lll(p) * aq) {
        ap = p;
        aq = q;
    }
}

int main() {
