    }
    sort(a, a + n, [] (st a, st b) {
                return max(a.a, a.b) > max(b.a, b.b);
            });
    sm[0] = 0;
    for (int i = 0; i < n; ++i) {
        sm[i + 1] = sm[i] + max(a[i].a, a[i].b);
    }
    for (int i = 0; i < n; ++i) {
        int l = 0;
        int r = n + 1;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            ll cur = sum - a[i].b - sm[m];
            if (i < m) {
                cur += max(a[i].a, a[i].b);
            }
            if (cur > 0) {
                l = m;
            } else {
                r = m;
            }
        }
        if (r <= n) {
            int cnt = r;
            if (i >= r) {
                ++cnt;
            }
            cnt = n - cnt;
            ll cur = sum - sm[r];
            if (i < r) {
                cur += max(a[i].a, a[i].b);
            }
            if (cur <= 0) {
                upd(cnt + 1, n);
            } else {
                assert(cur <= a[i].b);
                ll p = cnt * a[i].b + a[i].b - cur;
                ll q = a[i].b * n;
                upd(p, q);
            }
        }
    }
    cout << ap << " " << aq << "\n";
	return 0;
}

