int fact() {
  int x;string num;
  int mi=1;
  while(*p=='-') {
    mi*=-1;
    ++p;
  }
  while(isdigit(*p)){num+=*p;++p;}
  if(num.size()>1&&num[0]=='0') f[k]=0;
  if(num.size()) {
    x=0;
    for(int i=num.size()-1,j=0; i>=0; i--,j++) x+=(1<<j)*(num[i]=='1');
  } else if(p!=s[k].end()){
    if(*p!='(') f[k]=0;
    bool ff=(*p=='(');
    if(p!=s[k].end()&&*p=='(')++p;
    x=exp();
    if(ff&&*p!=')') f[k]=0;
    if(p!=s[k].end()&&*p==')')++p;
  } else f[k]=0;
  return x*mi;
}

int term() {
  int x=fact();
  while(*p=='*') {
    ++p;
    x*=fact();
  }
  return x;
}

int exp() {
  int x=term();
  while(*p=='+'||*p=='-') {
    if(*p=='+') {
      ++p;
      x+=term();
    } else {
      ++p;
      x-=term();
    }
  }
  return x;
}

