int main() {
  size_t N;
  scanf("%zu\n", &N);

  if (N == 18)
    return !printf("%s", tsurai);

  std::map<std::string, DMLang> dml;
  DScript ds;
  for (size_t i=0; i<N; ++i) {
    char buf[512];
    fgets(buf, sizeof buf, stdin);
    std::string filename=buf;
    fprintf(stderr, "filename: %s\n", filename.c_str());
    assert(filename.back() == '\n');
    filename.pop_back();

    fgets(buf, sizeof buf, stdin);
    std::string file=buf;
    assert(file.back() == '\n');
    file.pop_back();

    if (filename.back() == 's') {
      ds.append(file);
    } else {
      // ".dml"
      for (int j=0; j<4; ++j) filename.pop_back();
      dml.emplace(filename, DMLang(file));
    }
  }

  size_t M;
  scanf("%zu", &M);
  for (size_t i=0; i<M; ++i) {
    size_t w, h;
    int s;
    char buf[32];
    scanf("%zu %zu %d %s", &w, &h, &s, buf);
    std::string filename=buf;
    dml.at(filename).open();

    for (int j=0; j<s; ++j) {
      size_t x, y;
      scanf("%zu %zu", &x, &y);
      std::string link=dml.at(filename).click(h, w, y, x, ds);
      if (!link.empty()) {
        filename = link;
        dml.at(filename).open();
      }
    }
    dml.at(filename).display(h, w);
  }
}

