bool boxin(P p){
	return p.X>-EPS && p.X<50+EPS && p.Y>-EPS && p.Y<94+EPS; 
}

void removeOut(){
	rep(i,path.size()){
		bool flg = true;
		rep(j,path[i].size()-1){
			if(isCrossLL(path[i][j], path[i][j+1])){
				P p = crossP_LL(path[i][j], path[i][j+1]);
				path[i][j][1] = p;
				path[i][j+1][1] = p;
				if(!boxin(p))flg=false;
			}else{
				flg=false;
			}
		}
		if(!flg){
			path.erase(path.begin()+i);
			i--;
		}
	}
}

