		if (!i){
			if (flag[v[1]]) {
				dp[1] = 1;
			}
			continue;
		}
		if (v[i] < v[i + 1]) {
			if (v[i + 1] == MOD || flag[v[i + 1]]) {
				dp[i + 1] += dp[i];
				dp[i + 1] %= MOD;
			}
		}
		if (v[i] < v[i + 2]) {
			if (v[i + 2] == MOD || flag[v[i + 2]]) {
				dp[i + 2] += dp[i];
				dp[i + 2] %= MOD;
			}
		}
	}
	cout << dp[N + 1] << endl;
	return 0;
}

