        if (!bad[i ^ (1 << j)]) {
          isbad = false;
          break;
        }
      }
    }
    if (isbad) {
      bad[i] = 1;
      continue;
    }
    int res = 0;
    for (int j = 0; j < p; j++) {
      if (!((i >> j) & 1)) res += sum[j];
    }
