template <int mod>
struct Modular {
  int val;
  Modular(long long _val = 0) {
    if (_val < 0 || _val >= mod) {
      val = _val % mod;
      if (val < 0) {
        val += mod;
      }
    } else {
      val = _val;
    }
  }
  Modular operator+(const Modular& ot) const {
    int res = val + ot.val;
    if (res >= mod) {
      res -= mod;
    }
    return {res};
  }
  Modular operator-(const Modular& ot) const {
    int res = val - ot.val;
    if (res < 0) {
      res += mod;
    }
    return {res};
  }
  Modular operator*(const Modular& ot) const { return {1ll * val * ot.val}; }
  Modular& operator++() {
    val += 1;
    if (val == mod) {
      val = 0;
    }
    return *this;
  }
  Modular operator++(int) {
    Modular tmp(*this);
    operator++();
    return tmp;
  }
  void operator+=(const Modular& ot) {
    val += ot.val;
    if (val >= mod) {
      val -= mod;
    }
  }
  void operator-=(const Modular& ot) {
    val -= ot.val;
    if (val < 0) {
      val += mod;
    }
  }
  void operator*=(const Modular& ot) { val = 1ll * val * ot.val % mod; }
  bool operator==(const Modular& ot) const { return val == ot.val; }
  bool operator!=(const Modular& ot) const { return val != ot.val; }
};
