  for (lnt i = 0; i < (N); ++i) {
    lnt num;
    if (i == N - 1 - i) {
      num = nCrmod(N - 1, i, MOD);
    } else {
      num = nCrmod(N - 1, i, MOD);
    }
    num %= MOD;
    minus += num;
    minus %= MOD;
  }
  ans += MOD;
  ans -= minus;
  ans %= MOD;
  cout << ans << '\n';
}

