        cin >> a[i].second;
    sort(a + 1, a + 1 + n);
    int l = 1, r = 1;
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        ans += calc(l, r, a[i].first, a[i].second);
        l = a[i].first;
        r = a[i].second;
    }
    cout << ans<<'\n';

}

